// ============================================
// EXTRACT PAYMENT INTENT DATA
// ============================================

const input = $input.first().json;
const body = input.body || input;

const eventData = body.event_data || body;
const paymentIntent = eventData;

// Check metadata for certification/one-time purchase
const metadata = paymentIntent.metadata || {};
const productType = metadata.type || metadata.product_type;
const courseId = metadata.course_id;
const validityMonths = parseInt(metadata.validity_months) || 0;

// Check if this is a one-time course purchase
const isOnetime = productType === 'certification' || 
                  productType === 'one_time' ||
                  metadata.one_time === 'true';

return {
  event_id: body.event_id,
  payment_intent_id: paymentIntent.id,
  customer_id: paymentIntent.customer,
  amount: paymentIntent.amount,
  currency: paymentIntent.currency,
  status: paymentIntent.status,
  metadata: metadata,
  product_type: productType,
  course_id: courseId,
  validity_months: validityMonths,
  is_onetime: isOnetime,
  stripe_product_id: metadata.stripe_product_id,
  timestamp: new Date().toISOString()
};

// ============================================
// CHECK USER EXISTS
// ============================================

const apiResponse = $input.first().json;
const paymentData = $('Extract Payment Data').first().json;

if (apiResponse.error || apiResponse.statusCode >= 400 || !apiResponse.data) {
  return {
    success: false,
    error: {
      code: 404,
      message: `User not found for Stripe customer: ${paymentData.customer_id}`,
      status: 'USER_NOT_FOUND'
    },
    customer_id: paymentData.customer_id
  };
}

const user = apiResponse.data || apiResponse;

// Calculate expiration date
let expiresAt = null;
if (paymentData.validity_months > 0) {
  const expDate = new Date();
  expDate.setMonth(expDate.getMonth() + paymentData.validity_months);
  expiresAt = expDate.toISOString();
}

return {
  success: true,
  user_id: user.id,
  discord_id: user.discord_id,
  guild_id: user.guild_id,
  customer_id: paymentData.customer_id,
  payment_intent_id: paymentData.payment_intent_id,
  course_id: paymentData.course_id,
  stripe_product_id: paymentData.stripe_product_id,
  validity_months: paymentData.validity_months,
  expires_at: expiresAt,
  amount: paymentData.amount,
  event_id: paymentData.event_id
};

