// ============================================
// PREPARE REDIS EVENT
// ============================================

const apiResponse = $input.first().json;
const userData = $('Check User').first().json;

const success = !apiResponse.error && apiResponse.statusCode !== 500;

// Prepare event for Redis Stream (RFC-023 format)
const event = {
  event: 'course.access.granted',
  guild_id: userData.guild_id,
  timestamp: new Date().toISOString(),
  data: {
    user_id: userData.user_id,
    discord_id: userData.discord_id,
    course_id: userData.course_id,
    access_type: 'one_time',
    expires_at: userData.expires_at,
    payment_intent_id: userData.payment_intent_id
  }
};

return {
  event_id: userData.event_id,
  user_id: userData.user_id,
  discord_id: userData.discord_id,
  guild_id: userData.guild_id,
  course_id: userData.course_id,
  access_granted: success,
  expires_at: userData.expires_at,
  stream_name: 'learning:events:stream',
  event: event
};
